// Self-contained: serialized as a Vue method, with factories supplied by the node.
function createPanelMeterClient ({ socket, panelId, room, ids, request, createReceiver,
  createRenderer, apply, invalidate, onUnauthorized }) {
  if (!socket) throw Error('Dashboard socket is unavailable for meter telemetry')
  let auth = null, renderer = null, generation = 0, disposed = false
  let retry = null, stale = null, connecting = false, delay = 500
  const stopRendering = () => {
    renderer?.close(); renderer = null
    clearTimeout(stale); stale = null
    invalidate()
  }
  const pause = () => {
    generation++
    connecting = false
    clearTimeout(retry); retry = null
    if (socket.connected) socket.emit('control-panel:meter-unsubscribe', panelId)
    stopRendering()
  }
  const connect = async () => {
    if (disposed || !auth || document.hidden || !socket.connected || connecting) return
    clearTimeout(retry); retry = null
    connecting = true
    const expected = generation
    try {
      const { response, result } = await request(auth.endpoint + '/meter-ticket', {
        method: 'POST', credentials: 'same-origin',
        headers: { 'Content-Type': 'application/json', [auth.header]: auth.csrf },
        body: JSON.stringify({ room, socketId: socket.id })
      }, 5000, async response => ({ response, result: await response.json() }))
      if (disposed || expected !== generation || document.hidden) return
      if (response.status === 401) { pause(); auth = null; onUnauthorized(); return }
      if (!response.ok) throw Error(result.error || 'Meter subscription failed')
      delay = 500
      socket.emit('control-panel:meter-subscribe', panelId, result.ticket)
    } catch (_) {
      if (!disposed && expected === generation && auth) {
        retry = setTimeout(connect, delay)
        delay = Math.min(delay * 2, 5000)
      }
    } finally { if (expected === generation) connecting = false }
  }
  const ready = layout => {
    if (disposed || !auth || document.hidden || layout?.panelId !== panelId || layout.room !== room ||
      !Array.isArray(layout.ids) || JSON.stringify(layout.ids) !== JSON.stringify(ids)) return
    stopRendering()
    try {
      renderer = createRenderer({ receiver: createReceiver(layout),
        requestFrame: callback => requestAnimationFrame(callback), cancelFrame: cancelAnimationFrame,
        apply: frame => { apply(frame, ids) } })
    } catch (_) { stopRendering() }
  }
  const frame = message => {
    if (message?.panelId !== panelId || !auth || document.hidden || !renderer?.receive(message)) return
    clearTimeout(stale)
    stale = setTimeout(invalidate, 1500)
  }
  const ended = message => {
    if (message?.panelId !== panelId) return
    stopRendering()
    if (auth && !disposed && !retry) retry = setTimeout(connect, 500)
  }
  const disconnected = () => { generation++; connecting = false; stopRendering() }
  const visibility = () => { if (document.hidden) pause(); else void connect() }
  socket.on('control-panel:meter-ready', ready)
  socket.on('control-panel:meter-frame', frame)
  socket.on('control-panel:meter-ended', ended)
  socket.on('connect', connect)
  socket.on('disconnect', disconnected)
  document.addEventListener('visibilitychange', visibility)
  return {
    setAuth (next) { pause(); auth = next; delay = 500; if (auth) void connect() },
    close () {
      disposed = true; pause(); auth = null
      socket.off('control-panel:meter-ready', ready)
      socket.off('control-panel:meter-frame', frame)
      socket.off('control-panel:meter-ended', ended)
      socket.off('connect', connect)
      socket.off('disconnect', disconnected)
      document.removeEventListener('visibilitychange', visibility)
    }
  }
}

module.exports = { createPanelMeterClient }
